extra_css:
/* Ferrofluid surfaces: panels are drops of the fluid itself, mirror-black with a studio softbox reflection along the top edge and a
   cyan horizon rim; hovering a card pulls a magnetic bulge (scale + rim brighten). Full-fidelity: backdrop blur on every panel. */
html[data-atmo="ferro"] .card, html[data-atmo="ferro"] .panel, html[data-atmo="ferro"] .gx-card {
  background: radial-gradient(120% 60% at 30% -10%, rgba(255,255,255,.13), transparent 42%), linear-gradient(180deg, rgba(20,23,29,.82), rgba(4,5,7,.9));
  backdrop-filter: blur(14px) saturate(140%); -webkit-backdrop-filter: blur(14px) saturate(140%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.18), inset 0 -1px 0 rgba(111,231,255,.25), 0 20px 50px rgba(0,0,0,.7);
  transition: transform .35s cubic-bezier(.2,1.4,.4,1), box-shadow .35s; }
html[data-atmo="ferro"] .card:hover, html[data-atmo="ferro"] .gx-card:hover {
  transform: translateY(-3px) scale(1.012); box-shadow: inset 0 1px 0 rgba(255,255,255,.28), inset 0 -2px 0 rgba(111,231,255,.6), 0 26px 60px rgba(0,0,0,.8), 0 0 30px rgba(111,231,255,.12); }
html[data-atmo="ferro"] h1, html[data-atmo="ferro"] h2 { letter-spacing: -.01em; background: linear-gradient(180deg, #ffffff, #9aa6b4 55%, #e8f9ff); -webkit-background-clip: text; background-clip: text; color: transparent; }
@media (prefers-reduced-motion: reduce) { html[data-atmo="ferro"] .card, html[data-atmo="ferro"] .gx-card { transition: none; } }

